{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 공영주차장 1일주차권을 미리 샀는데 주차장 사정으로 오후 운영을 안 할 때 선불이라 못 돌려준다는 주장이 맞는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제18조제2항에 따르면, 공영노외주차장의 사용 중지·폐지 등 이용자에게 책임을 돌릴 수 없는 사유로 주차할 수 없게 된 때에는 이미 징수한 주차요금을 반환하여야 한다. 1일주차권의 경우 1일주차권 1매의 단가를 산출하여 사용할 수 없게 된 시간에 대한 금액을 반환한다. 따라서 주차장 사정으로 오후 운영을 하지 않아 주차할 수 없게 된 경우라면, 선불로 받았다는 이유만으로 전액 반환을 거절하는 것은 조례상 맞지 않고, 사용하지 못한 시간에 해당하는 금액을 반환받을 수 있다.",
          "b_ids": "주차장:제18조제2항, 주차장:제18조제2항제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
